 public List<Map<String,Object>> sitemap(){return tx.execute(s->{var rows=jdbc.query("SELECT i.locale,r.metadata::text,r.published_at FROM experience.content_item i JOIN experience.content_revision r ON r.id=i.current_published_revision_id WHERE i.status='ACTIVE' AND i.deleted_at IS NULL AND r.state='PUBLISHED' AND r.approved_by IS NOT NULL AND r.published_at<=? ORDER BY i.locale,i.content_type,i.slug LIMIT 10000",(r,n)->new Object[]{r.getString(1),EventCodec.JSON.readTree(r.getString(2)),r.getTimestamp(3).toInstant()},Timestamp.from(clock.instant()));var entries=new ArrayList<Map<String,Object>>();for(Object[] row:rows){JsonNode metadata=(JsonNode)row[1];JsonNode canonical=metadata.get("canonicalUrl");if(canonical==null||canonical.isNull())continue;String url=canonical.asString();try{if(!allowedHosts.contains(java.net.URI.create(url).getHost().toLowerCase(Locale.ROOT)))continue;}catch(Exception ignored){continue;}var alternates=new ArrayList<Map<String,String>>();for(JsonNode alt:metadata.path("alternates")){String target=alt.path("url").asString();if(allowedHosts.contains(java.net.URI.create(target).getHost().toLowerCase(Locale.ROOT)))alternates.add(Map.of("locale",alt.path("locale").asString(),"url",target));}entries.add(Map.of("url",url,"lastModified",row[2].toString(),"locale",row[0],"alternateUrls",alternates));}return List.copyOf(entries);});}
